def _get(name: str) -> List[float]:
    for n, v in EXPECTED:
        if n == name:
            return v
    raise ValueError("missing " + name)

def check(name: str, got, rtol: float = 1e-7, atol: float = 1e-10):
    want = _get(name)
    g = List[float]()
    for v in got:
        if isinstance(v, np.ndarray):
            for w in v.ravel():
                g.append(float(w))
        else:
            g.append(float(v))
    ok = len(g) == len(want)
    if ok:
        for i in range(len(want)):
            if abs(g[i] - want[i]) > atol + rtol * abs(want[i]):
                ok = False
    if not ok:
        print("TEST FAILED:", name, g, want)

rng = np.random.RandomState(0)
X = rng.randn(60, 4)
w = np.array([1.5, -2.0, 0.5, 0.0])
yr = X @ w + 0.3 * rng.randn(60)
yb = np.empty(60, dtype=int)
y3 = np.empty(60, dtype=int)
for i in range(60):
    yb[i] = 1 if X[i, 0] + X[i, 1] > 0.0 else 0
    d = X[i, 0] - X[i, 2]
    y3[i] = 0 if d < -0.5 else (1 if d < 0.5 else 2)
X10 = X[:10]

def clf(name: str, m, y):
    m.fit(X, y)
    check(name + "_coef", m.coef_)
    check(name + "_int", m.intercept_)
    check(name + "_meta", [float(m.n_iter_), float(m.t_)])
    check(name + "_pred", m.predict(X10))

